import pathlib,csv,json
p=pathlib.Path(__file__).resolve().parent
rows=list(csv.DictReader((p/'all-nets.csv').open(encoding='utf-8')))
assert len(rows)==646
data=json.dumps(rows,ensure_ascii=False).replace('</',r'<\/')
html='''<!doctype html><html lang="zh"><meta charset="utf-8"><title>A/B 全量真实连线负载统计</title>
<style>body{font:15px system-ui;margin:28px;color:#172b40;background:#f5f8fb}h1{font-size:25px}p{max-width:1100px;line-height:1.7}input,select{padding:10px;margin:8px;border:1px solid #acbdcc;border-radius:5px}table{border-collapse:collapse;background:white;width:100%;font-size:12px}th,td{padding:9px;border-bottom:1px solid #dce5ed;text-align:left;white-space:nowrap}th{position:sticky;top:0;background:#dce8f1;cursor:pointer}tr.bad td:nth-child(9){color:#af2534;font-weight:bold}#count{font-weight:bold;margin:12px}td{max-width:380px;overflow:hidden;text-overflow:ellipsis}.wrap{overflow:auto;max-height:70vh}small{color:#53687b}</style>
<h1>A/B 全量真实连线负载统计</h1><p>646 / 646 条方案—线网记录：A 306 根 C/U；B 306 根 C/U + 34 根 G/S。P 不评驱动，但金属保留在电场环境中。总负载 = 上层静态自电容 + 已知接收/源侧本地输入引脚电容，未包含块内线寄生和完整下层金属。未超已知负载不代表时序通过。R 是研究材料参数下的串联长度估计，不是联合 STA 的提取网络。</p>
<select id="scheme"><option value="">全部方案</option><option>A</option><option>B</option></select><select id="group"><option value="">全部通路</option><option>CU</option><option>GS</option></select><select id="state"><option value="">全部状态</option><option value="exceeds">负载超限</option><option value="not_exceeded_known_load">已知负载未超限</option></select><input id="search" size="40" placeholder="搜索线网、驱动、接收口或单元"><div id="count"></div><div class="wrap"><table><thead id="head"></thead><tbody id="body"></tbody></table></div><p><small>点击表头排序；悬停查看完整单元名。当前 C/U 为未验收 CTS 基底，G/S 原输入驱动需要切断确认。200/300 MHz setup/hold/slew 未验收。每一行均有实际场计算，未按抽样外推。</small></p>
<script>const data=DATA;
const cols=[['scheme','方案'],['group','通路'],['net','线网'],['driver','驱动口'],['sinks','接收口'],['length_um','长度 μm'],['wire_self_fF','线路 C fF'],['known_total_fF','已知总负载 fF'],['load_limit_ratio','负载/限值'],['limit_fF','库上限 fF'],['wire_coupling_fF','互容和 fF'],['series_R_estimate_ohm','R 估计 Ω'],['driver_cells','真实驱动单元'],['existing_sink_driver_terms','接收端既存驱动'],['relative_sigma','统计相对 σ']];
let key='load_limit_ratio',desc=true;const state=document.getElementById('state'),search=document.getElementById('search');const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
document.querySelector('#head').innerHTML='<tr>'+cols.map(([k,t])=>'<th data-key="'+k+'">'+t+'</th>').join('')+'</tr>';
function draw(){let filtered=data.filter(r=>['scheme','group'].every(k=>!document.getElementById(k).value||r[k]===document.getElementById(k).value)&&(!state.value||r.cap_status===state.value)&&JSON.stringify(r).toLowerCase().includes(search.value.toLowerCase()));filtered.sort((a,b)=>{let x=a[key],y=b[key];let d=x!==''&&y!==''&&!isNaN(Number(x))&&!isNaN(Number(y))?Number(x)-Number(y):x.localeCompare(y);return desc?-d:d});document.querySelector('#count').textContent='显示 '+filtered.length+' / 646 条；当前筛选超限 '+filtered.filter(r=>r.cap_status==='exceeds').length+' 条';document.querySelector('#body').innerHTML=filtered.map(r=>'<tr class="'+(r.cap_status==='exceeds'?'bad':'')+'">'+cols.map(([k])=>{let x=r[k];let v=['length_um','wire_self_fF','known_total_fF','load_limit_ratio','limit_fF','wire_coupling_fF','series_R_estimate_ohm'].includes(k)&&x!==''?Number(x).toFixed(2):x;return '<td title="'+esc(x)+'">'+esc(v)+'</td>'}).join('')+'</tr>').join('')};document.querySelectorAll('input,select').forEach(e=>e.addEventListener('input',draw));document.querySelectorAll('th').forEach(e=>e.onclick=()=>{desc=key===e.dataset.key?!desc:true;key=e.dataset.key;draw()});draw();</script></html>'''.replace('DATA',data)
(p/'all-nets.html').write_text(html,encoding='utf-8')
print('646-row standalone table written')
